# 3D-модель магазину взуття ТОВ «Взуття» (курсова робота, підрозділ 2.3).
# Запуск у SketchUp: Вікно → Консоль Ruby →  load "шлях/до/vzuttia.rb"
# або Розширення → (Extension Manager не потрібен) — просто load у консолі.
# Згенеровано build_model.py. Після побудови скрипт зберігає поруч vzuttia.skp,
# створює аркуш А1 vzuttia_A1.layout у LayOut і експортує його у vzuttia_A1.pdf.

